#include <iostream>
#include <typeinfo> // for typeid

int main() {
    int x = 27;
    const int& rx = x;

    // typeid on x (int) reports 'int'
    std::cout << typeid(x).name() << '\n';

    // typeid on rx (const int&) also reports 'int'.
    // The const and reference qualifiers are stripped.
    std::cout << typeid(rx).name() << '\n';

    // This can be misleading when debugging type deduction.
    return 0;
}
